import {
  DRAWER_CLOSE_EVENT,
  DRAWER_HOST_ATTR,
  DRAWER_LOGO_PX,
  DRAWER_OPEN_EVENT,
  sync_drawer_iframe_layout,
} from '../../界面/状态栏/util/sideDrawerHost';

export const FLOAT_LOGO_ATTR = 'data-zhuixing-float-logo';
export { DRAWER_CLOSE_EVENT, DRAWER_OPEN_EVENT };
const STYLE_ID = 'zhuixing-float-logo-style';

function logo_storage_key(): string {
  return `zhuixing-logo-pos:${SillyTavern.getCurrentChatId?.() ?? 'default'}`;
}

function read_saved_pos(): { x: number; y: number } | null {
  try {
    const raw = sessionStorage.getItem(logo_storage_key());
    if (!raw) {
      return null;
    }
    const parsed = JSON.parse(raw) as { x?: number; y?: number };
    if (Number.isFinite(parsed.x) && Number.isFinite(parsed.y)) {
      return { x: parsed.x!, y: parsed.y! };
    }
  } catch {
    /* ignore */
  }
  return null;
}

function save_pos(x: number, y: number): void {
  try {
    sessionStorage.setItem(logo_storage_key(), JSON.stringify({ x, y }));
  } catch {
    /* ignore */
  }
}

function default_pos(): { x: number; y: number } {
  const margin = 12;
  const vw = tavern_window().innerWidth;
  const vh = tavern_window().innerHeight;
  return {
    x: Math.max(margin, vw - DRAWER_LOGO_PX - margin),
    y: Math.max(margin + 48, Math.round(vh * 0.28)),
  };
}

function clamp_pos(x: number, y: number): { x: number; y: number } {
  const margin = 8;
  const vw = tavern_window().innerWidth;
  const vh = tavern_window().innerHeight;
  const max_x = Math.max(margin, vw - DRAWER_LOGO_PX - margin);
  const max_y = Math.max(margin, vh - DRAWER_LOGO_PX - margin);
  return {
    x: Math.min(Math.max(margin, x), max_x),
    y: Math.min(Math.max(margin, y), max_y),
  };
}

function tavern_window(): Window {
  try {
    if (window.parent && window.parent !== window) {
      return window.parent;
    }
  } catch {
    /* cross-origin */
  }
  return window;
}

function tavern_document(): Document {
  return tavern_window().document;
}

function inject_logo_style(): void {
  const doc = tavern_document();
  if (doc.getElementById(STYLE_ID)) {
    return;
  }
  const css = `
    button[${FLOAT_LOGO_ATTR}] {
      position: fixed;
      z-index: 10051;
      width: ${DRAWER_LOGO_PX}px;
      height: ${DRAWER_LOGO_PX}px;
      padding: 0;
      border: 2px solid #c8955c;
      border-radius: 12px;
      background: linear-gradient(145deg, #fffaf2 0%, #f0dcc0 55%, #e6c89a 100%);
      color: #5c4738;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      cursor: grab;
      box-shadow: 0 4px 14px rgba(92, 71, 56, 0.2);
      font-family: 'Nunito', 'Microsoft YaHei', ui-sans-serif, system-ui, sans-serif;
      overflow: hidden;
      touch-action: none;
      user-select: none;
    }
    button[${FLOAT_LOGO_ATTR}]:hover {
      box-shadow: 0 6px 18px rgba(92, 71, 56, 0.28);
      transform: translateY(-1px);
    }
    button[${FLOAT_LOGO_ATTR}].is-dragging {
      cursor: grabbing;
      transform: scale(1.04);
    }
    button[${FLOAT_LOGO_ATTR}] .logo-star {
      font-size: 0.82rem;
      line-height: 1;
      color: #c8955c;
    }
    button[${FLOAT_LOGO_ATTR}] .logo-text {
      font-size: 0.58rem;
      font-weight: 900;
      letter-spacing: 0.12em;
      line-height: 1.1;
      margin-top: 1px;
    }
  `;
  $('<style>').attr('id', STYLE_ID).text(css).appendTo($(doc.head));
}

export function $float_logo(): JQuery<HTMLButtonElement> {
  return $(`button[${FLOAT_LOGO_ATTR}]`, tavern_document()) as JQuery<HTMLButtonElement>;
}

let drag_active = false;
let drag_moved = false;
let drag_origin = { x: 0, y: 0 };
let drag_offset = { x: 0, y: 0 };
let drag_pointer_id: number | null = null;
let open_handler: (() => void) | undefined;
let bound_logo: HTMLButtonElement | null = null;
let drag_listeners_bound = false;

const CAPTURE = { capture: true } as const;

function apply_logo_pos(x: number, y: number): void {
  if (!bound_logo) {
    return;
  }
  bound_logo.style.left = `${x}px`;
  bound_logo.style.top = `${y}px`;
}

function on_drag_pointermove(event: PointerEvent): void {
  if (!drag_active || event.pointerId !== drag_pointer_id || !bound_logo) {
    return;
  }
  if (Math.hypot(event.clientX - drag_origin.x, event.clientY - drag_origin.y) > 6) {
    drag_moved = true;
  }
  const next = clamp_pos(event.clientX - drag_offset.x, event.clientY - drag_offset.y);
  apply_logo_pos(next.x, next.y);
}

function cleanup_drag_listeners(): void {
  if (!drag_listeners_bound) {
    return;
  }
  drag_listeners_bound = false;
  const doc = tavern_document();
  doc.removeEventListener('pointermove', on_drag_pointermove, CAPTURE);
  doc.removeEventListener('pointerup', on_drag_pointerup, CAPTURE);
  doc.removeEventListener('pointercancel', on_drag_pointerup, CAPTURE);
}

function on_drag_pointerup(event: PointerEvent): void {
  if (!drag_active || event.pointerId !== drag_pointer_id || !bound_logo) {
    return;
  }
  drag_active = false;
  drag_pointer_id = null;
  bound_logo.classList.remove('is-dragging');
  try {
    bound_logo.releasePointerCapture(event.pointerId);
  } catch {
    /* ignore */
  }
  cleanup_drag_listeners();

  const left = Number.parseFloat(bound_logo.style.left) || 0;
  const top = Number.parseFloat(bound_logo.style.top) || 0;
  save_pos(left, top);

  if (!drag_moved) {
    open_handler?.();
  }
}

function bind_drag_listeners(): void {
  if (drag_listeners_bound) {
    return;
  }
  drag_listeners_bound = true;
  const doc = tavern_document();
  doc.addEventListener('pointermove', on_drag_pointermove, CAPTURE);
  doc.addEventListener('pointerup', on_drag_pointerup, CAPTURE);
  doc.addEventListener('pointercancel', on_drag_pointerup, CAPTURE);
}

function bind_logo_drag($logo: JQuery<HTMLButtonElement>): void {
  const el = $logo[0];
  if (!el) {
    return;
  }
  $logo.off('.zhuixingLogo');
  bound_logo = el;
  el.onpointerdown = (event: PointerEvent) => {
    if (event.button !== 0) {
      return;
    }
    event.preventDefault();
    drag_active = true;
    drag_moved = false;
    drag_pointer_id = event.pointerId;
    drag_origin = { x: event.clientX, y: event.clientY };
    const left = Number.parseFloat(el.style.left) || 0;
    const top = Number.parseFloat(el.style.top) || 0;
    drag_offset = { x: event.clientX - left, y: event.clientY - top };
    el.classList.add('is-dragging');
    bind_drag_listeners();
    try {
      el.setPointerCapture(event.pointerId);
    } catch {
      /* ignore */
    }
  };
}

export function ensure_float_logo(on_open: () => void): JQuery<HTMLButtonElement> {
  open_handler = on_open;
  inject_logo_style();

  let $logo = $float_logo();
  if ($logo.length === 0) {
    $logo = $(`<button type="button" ${FLOAT_LOGO_ATTR} aria-label="打开部落状态栏">
      <span class="logo-star" aria-hidden="true">✦</span>
      <span class="logo-text">坠星</span>
    </button>`, tavern_document()).appendTo($(tavern_document().body)) as JQuery<HTMLButtonElement>;
  }

  const saved = read_saved_pos() ?? default_pos();
  const pos = clamp_pos(saved.x, saved.y);
  $logo.css({ left: pos.x, top: pos.y, display: 'flex' });
  bind_logo_drag($logo);
  return $logo;
}

export function show_float_logo(): void {
  const $logo = $float_logo();
  if ($logo.length === 0) {
    return;
  }
  const left = Number.parseFloat($logo.css('left')) || 0;
  const top = Number.parseFloat($logo.css('top')) || 0;
  const clamped = clamp_pos(left, top);
  $logo.css({ left: clamped.x, top: clamped.y, display: 'flex' });
}

export function hide_float_logo(): void {
  $float_logo().css('display', 'none');
}

export function show_modal_iframe(): void {
  sync_drawer_iframe_layout({ open: true, logo_x: 0, logo_y: 0 });
  const iframe = $(`iframe[${DRAWER_HOST_ATTR}]`, tavern_document())[0] as HTMLIFrameElement | undefined;
  if (iframe) {
    iframe.style.display = 'block';
  }
}

export function hide_modal_iframe(): void {
  sync_drawer_iframe_layout({ open: false, logo_x: 0, logo_y: 0 });
  const iframe = $(`iframe[${DRAWER_HOST_ATTR}]`, tavern_document())[0] as HTMLIFrameElement | undefined;
  if (iframe) {
    iframe.style.display = 'none';
  }
}

export function reposition_float_logo_on_resize(): void {
  const $logo = $float_logo();
  if ($logo.length === 0 || $logo.css('display') === 'none') {
    return;
  }
  const clamped = clamp_pos(Number.parseFloat($logo.css('left')) || 0, Number.parseFloat($logo.css('top')) || 0);
  $logo.css({ left: clamped.x, top: clamped.y });
}

export function dispatch_drawer_open(): void {
  const doc = ($(`iframe[${DRAWER_HOST_ATTR}]`, tavern_document())[0] as HTMLIFrameElement | undefined)?.contentDocument;
  doc?.dispatchEvent(new CustomEvent(DRAWER_OPEN_EVENT));
}

export function dispatch_drawer_close(): void {
  const doc = ($(`iframe[${DRAWER_HOST_ATTR}]`, tavern_document())[0] as HTMLIFrameElement | undefined)?.contentDocument;
  doc?.dispatchEvent(new CustomEvent(DRAWER_CLOSE_EVENT));
}

declare global {
  interface Window {
    __zhuixing_sync_float_logo?: (visible: boolean) => void;
    /** 状态栏 iframe 暴露给宿主的抽屉控制句柄（实现见 脚本/状态栏侧栏/SideDrawerApp.vue） */
    __zhuixing_drawer?: {
      open: () => void;
      close: () => void;
    };
  }
}

export function register_float_logo_bridge(): void {
  tavern_window().__zhuixing_sync_float_logo = visible => {
    if (visible) {
      hide_modal_iframe();
      show_float_logo();
      return;
    }
    hide_float_logo();
    show_modal_iframe();
  };
}
