/**
 * 面板改 stat 的统一入口。
 *
 * 抽屉的 store→MVU 深监听推写实测不可靠（改了 store.data 但 stat 没变），
 * 所以"改完必须落库"的面板操作统一走这里：getMvuData → mutate → replaceMvuData，
 * 再顺手改一次 store.data 让界面立刻响应。
 */

export const LATEST_OPTION = { type: 'message', message_id: 'latest' } as const

/** 直接改并写回 MVU；成功返回 true */
export async function write_stat_directly(mutate: (stat: any) => void): Promise<boolean> {
  try {
    const MvuGlobal = (globalThis as unknown as { Mvu?: any }).Mvu
    if (!MvuGlobal?.getMvuData || !MvuGlobal?.replaceMvuData) return false
    const mvu_data = MvuGlobal.getMvuData(LATEST_OPTION)
    if (!mvu_data?.stat_data) return false
    mutate(mvu_data.stat_data)
    await MvuGlobal.replaceMvuData(mvu_data, LATEST_OPTION)
    return true
  } catch (error) {
    console.warn('[面板] 直写 MVU 失败', error)
    return false
  }
}

/**
 * 改 MVU + 改本地 store（界面即时反馈）。
 * `mutate` 会被调两次：一次在 MVU 快照上，一次在 store.data 上。
 */
export async function write_stat_both(mutate: (stat: any) => void, local: () => void): Promise<boolean> {
  const ok = await write_stat_directly(mutate)
  if (!ok) {
    // 直写失败就不动本地：否则界面变了、存档没变，刷新即丢（审查 P2-3）
    console.warn('[面板] 直写失败，已跳过本地更新以保持界面与存档一致')
    return false
  }
  local()
  return true
}
