const ZERO_ACTION = { 探索: 0, 狩猎: 0, 采集: 0, 工作: 0, 带队: 0, 大成功: 0, 失败: 0 };

function core_npc_insert(
  name: keyof typeof CORE_NPC_SKILLS,
  draft: {
    职务: string;
    档位: string;
    体力: number;
    饱食度: number;
       好感度: number;
    心情: string;
    状态: string;
    当前位置: string;
    当前任务: string;
    当前想法: string;
    对视时: { 动作: string; 表情: string; 心里话: string };
  },
) {
  const race = CORE_WRECK_NPC_RACE[name];
  const 种族系 = name === '霜华' ? '食草' : name === '朔春' ? '食肉' : name === '林果' ? '杂食' : '食肉';
  return {
    op: 'insert' as const,
    path: `/具名NPC/${name}`,
    value: {
      种族: race,
      种族系,
      职务: draft.职务,
      档位: draft.档位,
      体力: draft.体力,
      饱食度: draft.饱食度,
      好感度: draft.好感度,
      心情: draft.心情,
      状态: draft.状态,
      当前位置: draft.当前位置,
      当前任务: draft.当前任务,
      孕期: '未孕',
      受孕日: 0,
      技能: { ...CORE_NPC_SKILLS[name] },
      行动履历: { ...ZERO_ACTION },
      互动状态: '无',
      当前想法: draft.当前想法,
      对视时: draft.对视时,
    },
  };
}

