export function build_wreck_opening_update_variable_block(): string {
  const patch = build_wreck_opening_json_patch();
  return dedent`
    <UpdateVariable>
    <Analysis>
    - Time passed: 迫降定稿开场，同一天傍晚（约 18:40，入夜前）
    - Dramatic update allowed: yes（开局定稿，初始化核心 NPC 与营地状态）
    - Baseline: 玩家仍在第一天，但已被琥珀当众收为营地一员；火塘刚重新点着
    - Touched: /世界/*、/营地/*（含族人构成、仓库、建筑）、/部族事务、/主角/*、/探索区域、/具名NPC/*
    - Skipped: 探索编队、工作队列（尚未发生）
    - NPC fields: 四名核心成员 insert，含当前想法与对视时
    - Settlement: 无
    </Analysis>
    <JSONPatch>
    ${JSON.stringify(patch, null, 2)}
    </JSONPatch>
    </UpdateVariable>
  `;
}

function resolve_previous_mvu_data(message_id: number): Record<string, unknown> {
  if (message_id > 0) {
    const prev = Mvu.getMvuData({ type: 'message', message_id: message_id - 1 });
    if (prev && Object.keys(prev).length > 0) {
      return prev;
    }
  }
  const floor0 = Mvu.getMvuData({ type: 'message', message_id: 0 });
  return floor0 ?? {};
}

/** 解析定稿楼层内的 UpdateVariable 并写回该楼层 MVU */
export async function apply_wreck_opening_variables_from_message(
  message_id: number,
  message: string,
): Promise<boolean> {
  await waitGlobalInitialized('Mvu');
  markStatusBarLocalMutation(15000);

  const old_data = resolve_previous_mvu_data(message_id);
  const parsed = await Mvu.parseMessage(message, old_data);
  if (!parsed) {
    console.warn('[迫降定稿] parseMessage 未返回变量更新，尝试 NPC 面板同步');
    return false;
  }

  await Mvu.replaceMvuData(parsed, { type: 'message', message_id });

  await syncNpcPanelsFromMessage(message_id);

  const store = useDataStore();
  const stat_data = _.get(Mvu.getMvuData({ type: 'message', message_id }), 'stat_data', {});
  const result = Schema.safeParse(stat_data);
  if (result.success) {
    Object.assign(store.data, result.data);
  }

  console.info('[迫降定稿] 已从楼层 UpdateVariable 解析并写入 stat_data', message_id);
  return true;
}
