import { appendInputLine } from './chatInput';
import { markStatusBarLocalMutation } from './useStatusBarMutation';
import { pushUndoSnapshot } from './useActionUndo';

/** 从指令文本里提炼一句给玩家看的标签，例如「[外出采集] 队伍「采集队」前往「湖畔营地」…」→「采集队 · 外出采集 · 湖畔营地」 */
function describe_action(text: string): string {
  const cmd = (text.match(/^\[([^\]]+)\]/) ?? [])[1]
  const squad = (text.match(/队伍「([^」]+)」/) ?? [])[1]
  const area = (text.match(/前往「([^」]+)」/) ?? [])[1]
  const parts = [squad, cmd, area].filter(Boolean)
  return parts.length ? parts.join(' · ') : text.slice(0, 18) || '本次操作'
}

/** 仅追加聊天输入栏文本，不记录撤回点 */
export async function sendUserAction(message: string) {
  await appendInputLine(message);
}

/**
 * 标准交互：先记录撤回点 → 修改 store → 追加输入栏（未发送前可点「撤回」还原）
 */
export async function runUserAction(message: string, mutate: () => void | Promise<void>) {
  const text = message.trim();
  pushUndoSnapshot(text || undefined, describe_action(text));
  markStatusBarLocalMutation(10000);
  await mutate();
  if (text) {
    await appendInputLine(text);
  }
}

/** 仅修改 store、不写输入栏 */
export function runStoreAction(mutate: () => void, label = '本地操作') {
  pushUndoSnapshot(undefined, label);
  markStatusBarLocalMutation();
  mutate();
}

export { removeInputLine } from './chatInput';
