import _ from 'lodash';
import type { BuildingScale } from '../../../util/estimateFacilityPlan';
import { WORK_PROJECT_CATALOG } from './workProjectCatalog';
import { SCALE_FACTOR } from '../../../util/estimateFacilityPlan';

export type TechBuilding = {
  name: string;
  description: string;
  effect: string;
  materials: Record<string, number>;
  hours: number;
  /** 须已写入【已解锁科技】；null 表示开局可用 */
  unlockTech: string | null;
  prerequisite?: string;
  defaultScale?: BuildingScale;
};

/**
 * 「规划新设施」可选的建筑清单——由 WORK_PROJECT_CATALOG 派生（只取 type === '建造'）。
 * 这样建筑只维护一份：生产队列不再出现建造项，建造一律从这里进入。
 */

/** 「坚固木材×6, 干草×8」→ { 坚固木材: 6, 干草: 8 } */
function parseMaterials(text: string): Record<string, number> {
  const out: Record<string, number> = {};
  for (const seg of String(text ?? '').split(/[,，]/)) {
    const m = seg.trim().match(/^(.+?)\s*[×x*]\s*(\d+(?:\.\d+)?)$/);
    if (m) out[m[1].trim()] = Number(m[2]);
  }
  return out;
}

