export const TECH_BUILDING_CATALOG: TechBuilding[] = WORK_PROJECT_CATALOG
  .filter((p) => p.type === '建造')
  .map((p) => ({
    name: p.name,
    description: BUILDING_DESC[p.name] ?? '由首领规划的新设施',
    effect: BUILDING_EFFECT[p.name] ?? '改善营地条件',
    materials: parseMaterials(p.materials),
    hours: p.hours,
    unlockTech: p.tech ?? null,
    prerequisite: p.tech ? `需先研发「${p.tech}」` : '无需前置科技',
  }));

/** 按建筑大小缩放材料与工时（建筑大小概念已从 UI 移除，此函数保留给旧调用方） */
export function scaleBuildingMaterials(
  materials: Record<string, number>,
  hours: number,
  scale: BuildingScale,
): { materials: Record<string, number>; hours: number } {
  const factor = SCALE_FACTOR[scale] ?? 1;
  return {
    materials: _.mapValues(materials, (v) => Math.max(1, Math.round(Number(v) * factor))),
    hours: Math.max(1, Math.round(Number(hours) * factor * 10) / 10),
  };
}

/** 是否已解锁：unlockTech 为空表示开局可用 */
export function isTechBuildingUnlocked(building: TechBuilding, unlocked: string[] | undefined): boolean {
  if (!building.unlockTech) {
    return true;
  }
  return Array.isArray(unlocked) && unlocked.includes(building.unlockTech);
}

/** 未解锁时展示的前置说明 */
export function techBuildingPrerequisite(building: TechBuilding): string {
  return building.prerequisite ?? `需先解锁「${building.unlockTech ?? '相关科技'}」`;
}
