\n  border-radius: 10px;\r\n  background: #fcf8f0;\r\n  color: #6b4c3a;\r\n  font-size: 0.68rem;\r\n  font-weight: 900;\r\n  cursor: pointer;\r\n  white-space: nowrap;\r\n\r\n  &:hover:not(:disabled) {\r\n    background: #f4ecdb;\r\n    border-color: #a88a6d;\r\n  }\r\n\r\n  &:disabled {\r\n    opacity: 0.45;\r\n    cursor: not-allowed;\r\n  }\r\n}\r\n\r\n:deep(.top-user) {\r\n  flex-shrink: 0;\r\n}\r\n\r\n.content-area {\r\n  flex: 1 1 auto;\r\n  min-height: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  padding: 6px 14px 22px;\r\n}\r\n\r\n.content-wrap {\r\n  flex: 1 1 auto;\r\n  min-height: 0;\r\n  max-width: 56rem;\r\n  margin: 0 auto;\r\n  min-width: 0;\r\n  width: 100%;\r\n  position: relative;\r\n}\r\n\r\n.content-wrap > :not([style*='display: none']) {\r\n  width: 100%;\r\n}\r\n\r\n.paw-layer {\r\n  position: absolute;\r\n  inset: 0;\r\n  pointer-events: none;\r\n  overflow: hidden;\r\n  opacity: 0.12;\r\n  z-index: 0;\r\n}\r\n\r\n.paw {\r\n  position: absolute;\r\n}\r\n\r\n.paw-1 {\r\n  top: -40px;\r\n  left: -40px;\r\n  transform: rotate(45deg);\r\n  opacity: 0.5;\r\n}\r\n\r\n.paw-2 {\r\n  top: 140px;\r\n  left: 100px;\r\n  transform: rotate(60deg);\r\n  opacity: 0.4;\r\n}\r\n\r\n.paw-3 {\r\n  bottom: 30px;\r\n  right: 24px;\r\n  transform: rotate(-12deg);\r\n  opacity: 0.5;\r\n}\r\n\r\n.paw-4 {\r\n  top: 28%;\r\n  right: 22%;\r\n  transform: rotate(80deg);\r\n  opacity: 0.6;\r\n}\r\n"],"sourceRoot":""}]);
