: 0.68rem;\n  font-weight: 800;\n  font-family: inherit;\n  cursor: pointer;\n  white-space: nowrap;\n\n  &:hover:not(:disabled) {\n    border-color: #c8955c;\n    color: #5c4738;\n  }\n\n  &:disabled {\n    opacity: 0.45;\n    cursor: not-allowed;\n  }\n}\n\n.custom-eyebrow {\n  margin: 0 0 4px;\n  font-size: 0.68rem;\n  font-weight: 800;\n  letter-spacing: 0.18em;\n  color: #a88a6d;\n}\n\n.custom-title {\n  margin: 0;\n  font-size: 1.45rem;\n  font-weight: 900;\n  color: #4a3b32;\n}\n\n.sections {\n  max-height: min(58vh, 420px);\n  overflow-y: auto;\n  overflow-x: hidden;\n  padding-right: 4px;\n  margin-bottom: 16px;\n}\n\n.section-block {\n  margin-bottom: 18px;\n\n  &:last-child {\n    margin-bottom: 0;\n  }\n}\n\n.section-head {\n  margin-bottom: 10px;\n}\n\n.section-title {\n  margin: 0 0 4px;\n  font-size: 0.92rem;\n  font-weight: 900;\n  color: #5c4738;\n}\n\n.section-hint {\n  margin: 0;\n  font-size: 0.72rem;\n  font-weight: 700;\n  color: #a88a6d;\n  line-height: 1.5;\n}\n\n.option-grid {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.option-chip {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 4px;\n  width: 100%;\n  padding: 10px 12px;\n  border: 2px solid #e4d4ba;\n  border-radius: 12px;\n  background: #fffdf8;\n  text-align: left;\n  cursor: pointer;\n  font-family: inherit;\n  transition: all 0.15s ease;\n\n  &:hover {\n    border-color: #d4c2a4;\n  }\n\n  &.selected {\n    border-color: #7ca982;\n    background: #f4faf5;\n    box-shadow: 0 0 0 2px rgba(124, 169, 130, 0.18);\n  }\n}\n\n.chip-label {\n  font-size: 0.84rem;\n  font-weight: 900;\n  color: #4a3b32;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.chip-diff {\n  font-size: 0.62rem;\n  font-weight: 800;\n  color: #8c7462;\n  background: #f4ecdb;\n  padding: 1px 6px;\n  border-radius: 999px;\n}\n\n.chip-detail {\n  font-size: 0.72rem;\n  font-weight: 700;\n  color: #8c7462;\n  line-height: 1.45;\n}\n\n.custom-field {\n  display: block;\n  margin-top: 10px;\n}\n\n.field-label {\n  display: block;\n  margin-bottom: 6px;\n  font-size: 0.72rem;\n  font-weight: 800;\n  color: #c8955c;\n}\n\n.custom-input {\n  width: 100%;\n  padding: 10px 12px;\n  border: 2px dashed #c8955c;\n  border-radius: 10px;\n  background: #fffdf8;\n  color: #5c4738;\n  font-size: 0.82rem;\n  font-weight: 700;\n  font-family: inherit;\n  line-height: 1.55;\n  resize: vertical;\n  box-sizing: border-box;\n\n  &:focus {\n    outline: none;\n    border-color: #7ca982;\n    box-shadow: 0 0 0 2px rgba(124, 169, 130, 0.2);\n  }\n\n  &::placeholder {\n    color: #b5a389;\n    font-weight: 600;\n  }\n}\n\n.custom-actions {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding-top: 4px;\n  border-top: 2px dashed #e4d4ba;\n}\n\n.ghost-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 11px 14px;\n  border: 2px solid #e4d4ba;\n  border-radius: 12px;\n  background: #fcf8f0;\n  color: #8c7462;\n  font-size: 0.82rem;\n  font-weight: 800;\n  font-family: inherit;\n  cursor: pointer;\n\n  &:hover {\n    border-color: #d4c2a4;\n    color: #5c4738;\n  }\n}\n\n.custom-enter-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 13px 22px;\n  font-size: 0.92rem;\n  font-weight: 900;\n  font-family: inherit;\n  border: 2px solid #c8955c;\n  border-radius: 12px;\n  background: linear-gradient(180deg, #f0c999 0%, #e6b981 45%, #d9a86a 100%);\n  color: #634326;\n  box-shadow: 0 4px 0 #c8955c, inset 0 1px 0 rgba(255, 255, 255, 0.35);\n  cursor: pointer;\n  transition: all 0.15s ease;\n\n  &:hover:not(:disabled) {\n    background: linear-gradient(180deg, #f5d4a8 0%, #ecc18f 45%, #e0b075 100%);\n    transform: translateY(2px);\n    box-shadow: 0 2px 0 #c8955c, inset 0 1px 0 rgba(255, 255, 255, 0.35);\n  }\n\n  &:active:not(:disabled) {\n    transform: translateY(4px);\n    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2);\n  }\n\n  &:disabled {\n    opacity: 0.75;\n    cursor: wait;\n  }\n}\n\n.error-text {\n  margin: 10px 0 0;\n  font-size: 0.78rem;\n  font-weight: 700;\n  color: #d9776c;\n  text-align: center;\n}\n"],"sourceRoot":""}]);
