import type { MaterialGrade } from '../../../constants/gradeSystem';
import { material_grade_for } from '../../../constants/gradeSystem';
import { normalize_warehouse_item_name, warehouse_slot_meta, type WarehouseTopCategory } from '../../../constants/warehouseCatalog';
import type { SquadActionKey } from './squadActionMechanism';
import {
  clamp_pack_skill_bonus,
  format_pack_bonus_text,
  pack_bonus_for_item,
  pack_item_hint,
  pack_weight_for_item,
  type PackSkillBonus,
} from './packCategoryBonus';
import { packHasLighting } from './nightExploration';

export { PACK_BONUS_CAP_PER_SKILL, PACK_GRADE_POINTS } from './packCategoryBonus';
export type { PackSkillBonus } from './packCategoryBonus';

/** 出行背包负重上限 */
export const SQUAD_PACK_MAX_WEIGHT = 15;

export type WarehousePackItem = {
  id: string;
  label: string;
  stock: number;
  weight: number;
  hint: string;
  grade: MaterialGrade;
  category: WarehouseTopCategory;
  subcategory: string;
  /** 单件（×1）加成，展示用 */
  bonus: PackSkillBonus;
};

const CATEGORY_ORDER: WarehouseTopCategory[] = [
  '食物',
  '材料',
  '燃料',
  '医疗',
  '工具与装备',
  '珍异储备',
];

export function listWarehousePackItems(
  reserves: Record<string, { 当前: number; 上限: number }>,
  mode: SquadActionKey,
  inventory?: Record<string, { 数量: number; 描述?: string }>,
): WarehousePackItem[] {
  const merged = new Map<string, { 当前: number; 上限: number }>();
  for (const [rawId, slot] of Object.entries(reserves)) {
    if (slot.当前 <= 0) continue;
    const id = normalize_warehouse_item_name(rawId);
    const prev = merged.get(id);
    if (prev) {
      prev.当前 += slot.当前;
      prev.上限 = Math.max(prev.上限, slot.上限);
    } else {
      merged.set(id, { ...slot });
    }
  }

  // 物品栏（装备/工具）也算可用物资：上限按 200 兜底
  for (const [rawId, slot] of Object.entries(inventory ?? {})) {
    const qty = Number(slot?.数量 ?? 0);
    if (qty <= 0) continue;
    const id = normalize_warehouse_item_name(rawId);
    const prev = merged.get(id);
    if (prev) {
      prev.当前 += qty;
      prev.上限 = Math.max(prev.上限, 200);
    } else {
      merged.set(id, { 当前: qty, 上限: 200 });
    }
  }

  // 驾驶员要求：只保留对本次行动有加成的物资，纯占负重的（普通木柴之类）不再列进背包
  const useful = [...merged.entries()].filter(([id]) => {
    const bonus = pack_bonus_for_item(id, mode)
    return Object.values(bonus).some((v) => Number(v) > 0) || /* 照明物也算有用 */ packHasLighting({ [id]: 1 })
  })
  return useful
    .map(([id, r]) => {
      const slotMeta = warehouse_slot_meta(id);
      return {
        id,
        label: id,
        stock: r.当前,
        weight: pack_weight_for_item(id),
        hint: pack_item_hint(id, mode),
        grade: material_grade_for(id),
        category: slotMeta.top,
        subcategory: slotMeta.sub,
        bonus: pack_bonus_for_item(id, mode),
      };
    })
    .sort((a, b) => {
      const ca = CATEGORY_ORDER.indexOf(a.category);
      const cb = CATEGORY_ORDER.indexOf(b.category);
      if (ca !== cb) return ca - cb;
      const gradeRank = { 稀世: 0, 罕见: 1, 少有: 2, 普通: 3, 常见: 4 } as const;
      const ga = gradeRank[a.grade] ?? 5;
      const gb = gradeRank[b.grade] ?? 5;
      if (ga !== gb) return ga - gb;
      return a.label.localeCompare(b.label, 'zh-CN');
    });
}

export function getItemPackWeight(itemId: string): number {
  return pack_weight_for_item(itemId);
}

export function calcPackBonus(
  loadout: Record<string, number> | undefined,
  mode: SquadActionKey,
): PackSkillBonus & { weight: number } {
  const bonus = { 狩猎: 0, 战斗: 0, 采集: 0, 后勤: 0, weight: 0 };
  if (!loadout) return bonus;

  for (const [itemId, qty] of Object.entries(loadout)) {
    if (qty <= 0) continue;
    const id = normalize_warehouse_item_name(itemId);
    bonus.weight += pack_weight_for_item(id) * qty;
    const perUnit = pack_bonus_for_item(id, mode);
    for (const key of ['狩猎', '战斗', '采集', '后勤'] as const) {
      bonus[key] += (perUnit[key] ?? 0) * qty;
    }
  }

  const clamped = clamp_pack_skill_bonus(bonus);
  return { ...bonus, ...clamped, weight: bonus.weight };
}

export function formatPackLoadout(loadout: Record<string, number> | undefined): string {
  if (!loadout) return '无';
  const parts = Object.entries(loadout)
    .filter(([, qty]) => qty > 0)
    .map(([id, qty]) => `${normalize_warehouse_item_name(id)}×${qty}`);
  return parts.length ? parts.join('、') : '无';
}

export function formatPackBonusText(bonus: PackSkillBonus): string {
  return format_pack_bonus_text(bonus);
}
