import { has_game_started } from '../util/gameStarted';
function resolve_initial_phase() {
    if (has_game_started()) {
        return 'game';
    }
    // 第 0 层已有欢迎卡片，仍从标题屏进入完整开局流程
    return 'title';
}
const phase = ref(resolve_initial_phase());
/** 获取当前聊天最新楼层号；无消息时视为 0 */
export function get_latest_floor() {
    if (typeof getChatMessages !== 'function') {
        return 0;
    }
    const latest = getChatMessages(-1)[0];
    return latest?.message_id ?? 0;
}
export function is_floor_zero() {
    return get_latest_floor() === 0;
}
export function useGameFlow() {
    function enter_tent() {
        if (has_game_started()) {
            phase.value = 'game';
            return;
        }
        phase.value = 'route';
    }
    function open_custom() {
        phase.value = 'custom';
    }
    function open_companions() {
        if (has_game_started()) {
            phase.value = 'game';
            return;
        }
        phase.value = 'companions';
    }
    function back_to_custom() {
        if (has_game_started()) {
            phase.value = 'game';
            return;
        }
        phase.value = 'custom';
    }
    function enter_game() {
        phase.value = 'game';
    }
    function back_to_title() {
        if (has_game_started()) {
            phase.value = 'game';
            return;
        }
        phase.value = 'title';
    }
    function back_to_route() {
        phase.value = 'route';
    }
    return {
        phase,
        enter_tent,
        open_custom,
        open_companions,
        back_to_custom,
        enter_game,
        back_to_title,
        back_to_route,
        is_floor_zero,
    };
}
