import { klona } from 'klona';
import { DEFAULT_MEMBER_AVATARS } from '../constants/defaultAvatars';
const UI_KEY = '兽耳娘界面';
const default_ui = () => ({
    chief_avatar: '',
    member_avatars: {},
    hidden_areas: [],
});
function load_ui() {
    if (typeof getVariables !== 'function') {
        return default_ui();
    }
    const raw = getVariables({ type: 'chat' })[UI_KEY];
    return {
        ...default_ui(),
        ...(typeof raw === 'object' && raw !== null ? raw : {}),
    };
}
let shared_ui = null;
function ui_value() {
    shared_ui = shared_ui ?? ref(load_ui());
    return shared_ui.value;
}
export function useUiStore() {
    shared_ui = shared_ui ?? ref(load_ui());
    const ui = shared_ui;
    function persist() {
        if (typeof updateVariablesWith !== 'function') {
            return;
        }
        updateVariablesWith(variables => {
            variables[UI_KEY] = klona(ui.value);
            return variables;
        }, { type: 'chat' });
    }
    watch(ui, persist, { deep: true });
    function set_chief_avatar(data_url) {
        ui.value.chief_avatar = data_url;
    }
    function set_member_avatar(name, data_url) {
        ui.value.member_avatars[name] = data_url;
    }
    function get_member_avatar(name) {
        return ui.value.member_avatars[name] ?? DEFAULT_MEMBER_AVATARS[name] ?? '';
    }
    function hide_area(name) {
        if (!ui.value.hidden_areas.includes(name)) {
            ui.value.hidden_areas.push(name);
        }
    }
    return { ui, set_chief_avatar, set_member_avatar, get_member_avatar, hide_area };
}
/**
 * 取界面状态快照（撤回用）。
 * 为什么单独导出：`hidden_areas` 这类状态存在 chat 变量里、不属于 stat_data，
 * 撤回时如果只回滚 stat，就会出现「变量回去了、区域还是被隐藏」（实机反馈）。
 * 按 Claude 的边界判断：它不参与规则计算，不该挪进 stat，而应该纳入同一个事务快照。
 */
export function snapshot_ui_state() {
    return klona(ui_value());
}
/** 还原界面状态（撤回用） */
export function restore_ui_state(snap) {
    if (!snap)
        return;
    const target = ui_value();
    target.chief_avatar = snap.chief_avatar ?? '';
    target.member_avatars = klona(snap.member_avatars ?? {});
    target.hidden_areas = [...(snap.hidden_areas ?? [])];
}
export function read_image_file(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
    });
}
